export function resolveMutationNode(policy, operation, collection) {
    const node = operation === 'update' ? policy?.update : policy?.delete;
    if (node === false) {
        invalid('WRITE_FORBIDDEN', `${operation} is forbidden by Policy.`, {
            collection: collection.name,
        });
    }
    return node;
}

export function composeDatabasePolicies(checks) {
    const policies = Object.create(null);
    for (const check of checks) {
        if (check.resource.type !== 'database.collection')
            continue;
        const policy = (policies[check.resource.id] ??= {
            read: false,
            create: false,
            update: false,
            delete: false,
        });
        switch (check.action) {
            case 'read':
                policy.read = foldDecision('read', check.decision);
                break;
            case 'create':
                policy.create = foldDecision('create', check.decision);
                break;
            case 'update':
                policy.update = foldDecision('update', check.decision);
                break;
            case 'delete':
                policy.delete = foldDecision('delete', check.decision);
                break;
        }
    }
    return policies;
}

